// Detection test with synthetic HTML via fetch stub.
import worker from "./index.js";

const CASES = {
  "https://chatty.example/": `<html><head><script src="https://widget.intercom.io/widget/abc123"></script></head><body><h1>Welcome</h1></body></html>`,
  "https://disclosed.example/": `<html><body><script>window.$crisp=[];</script><script src="https://client.crisp.chat/l.js"></script><div>You are chatting with an AI assistant.</div></body></html>`,
  "https://labeled.example/": `<html><body><article>This image was generated by AI.</article></body></html>`,
  "https://aiwidget.example/": `<html><body><script src="https://cdn.chatbase.co/embed.min.js"></script><footer>powered by AI</footer></body></html>`,
};

const realFetch = globalThis.fetch;
globalThis.fetch = async (u, opts) => {
  const key = String(u);
  if (CASES[key]) return new Response(CASES[key], { status: 200, headers: { "content-type": "text/html" } });
  return realFetch(u, opts);
};

const store = new Map();
const env = {
  CHECKER: { async get(k) { return store.get(k) ?? null; }, async put(k, v) { store.set(k, v); } },
  WORKER_ORIGIN: "http://local.test", BOT_USERNAME: "TestBot", BOT_TOKEN: "T", WEBHOOK_SECRET: "s",
};

for (const target of Object.keys(CASES)) {
  const res = await worker.fetch(new Request("http://local.test/scan?url=" + encodeURIComponent(target)), env);
  const j = await res.json();
  console.log(target, "->", j.report && j.report.verdict, JSON.stringify(j.report && j.report.checks.map(c => c.id + ":" + c.status)));
}

// invalid url after tightening
const res = await worker.fetch(new Request("http://local.test/scan?url=notaurl.."), env);
console.log("notaurl.. ->", res.status, JSON.stringify(await res.json()));
